package com.alsafa.native4.core;

import android.content.ContentValues;import android.content.Context;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import android.database.sqlite.SQLiteOpenHelper;import com.alsafa.native4.sync.SyncOperation;
/** Production core DB for Native4. Local data is authoritative; upgrades are additive. */
public final class CoreDb extends SQLiteOpenHelper implements CoreStore.DbProvider {
 public CoreDb(Context context){super(context,"alsafa_native4_core.db",null,22);}
 @Override public void onCreate(SQLiteDatabase db){createSyncTables(db);CoreSchemaV8.create(db);CoreSchemaV11.create(db);CoreSchemaV12.create(db);CoreSchemaV13.create(db);CoreSchemaV14.create(db);CoreSchemaV15.create(db);CoreSchemaV16.create(db);CoreSchemaV17.create(db);CoreSchemaV18.create(db);CoreSchemaV19.create(db);CoreSchemaV20.create(db);CoreSchemaV21.create(db);CoreSchemaV22.create(db);}
 @Override public void onUpgrade(SQLiteDatabase db,int oldVersion,int newVersion){createSyncTables(db);CoreSchemaV8.create(db);if(oldVersion<10){addColumnIfMissing(db,"daily_closings","carry_usd","REAL NOT NULL DEFAULT 0");addColumnIfMissing(db,"daily_closings","drawer_out_usd","REAL NOT NULL DEFAULT 0");addColumnIfMissing(db,"daily_closings","carry_try","REAL NOT NULL DEFAULT 0");addColumnIfMissing(db,"daily_closings","drawer_out_try","REAL NOT NULL DEFAULT 0");addColumnIfMissing(db,"daily_closings","carry_syp","REAL NOT NULL DEFAULT 0");addColumnIfMissing(db,"daily_closings","drawer_out_syp","REAL NOT NULL DEFAULT 0");}if(oldVersion<11)CoreSchemaV11.create(db);if(oldVersion<12)CoreSchemaV12.create(db);if(oldVersion<13)CoreSchemaV13.create(db);if(oldVersion<14)CoreSchemaV14.create(db);if(oldVersion<15)CoreSchemaV15.create(db);if(oldVersion<16)CoreSchemaV16.create(db);if(oldVersion<17)CoreSchemaV17.create(db);if(oldVersion<18)CoreSchemaV18.create(db);if(oldVersion<19)CoreSchemaV19.create(db);if(oldVersion<20)CoreSchemaV20.create(db);if(oldVersion<21)CoreSchemaV21.create(db);if(oldVersion<22)CoreSchemaV22.create(db);}
 private static void addColumnIfMissing(SQLiteDatabase db,String table,String column,String definition){try(Cursor c=db.rawQuery("PRAGMA table_info("+table+")",null)){while(c.moveToNext())if(column.equals(c.getString(c.getColumnIndexOrThrow("name"))))return;}db.execSQL("ALTER TABLE "+table+" ADD COLUMN "+column+" "+definition);}
 private static void createSyncTables(SQLiteDatabase db){db.execSQL("CREATE TABLE IF NOT EXISTS outbox(operation_id TEXT PRIMARY KEY,operation_kind TEXT NOT NULL,record_id TEXT NOT NULL,payload TEXT NOT NULL,source_device_id TEXT NOT NULL,created_at INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,last_attempt_at INTEGER,last_error TEXT,confirmed_revision INTEGER)");db.execSQL("CREATE TABLE IF NOT EXISTS applied(operation_id TEXT PRIMARY KEY,applied_at INTEGER NOT NULL)");db.execSQL("CREATE TABLE IF NOT EXISTS sync_checkpoint(checkpoint_key TEXT PRIMARY KEY,checkpoint_value TEXT NOT NULL,updated_at INTEGER NOT NULL)");}
 @Override public SQLiteDatabase db(){return getWritableDatabase();}@Override public void enqueue(SQLiteDatabase db,SyncOperation op){op.validate();ContentValues v=new ContentValues();v.put("operation_id",op.id);v.put("operation_kind",op.kind.name());v.put("record_id",op.recordId);v.put("payload",op.payload);v.put("source_device_id",op.sourceDeviceId);v.put("created_at",op.createdAt);v.put("state","PENDING");if(db.insertWithOnConflict("outbox",null,v,SQLiteDatabase.CONFLICT_IGNORE)==-1)throw new IllegalStateException("تعذر حفظ أمر المزامنة");}
}
